-- Bring stray Polytown towns back to the others. Founding used to resume a
-- spiral cursor that only moved outward, so some mayors were planted far from
-- everybody else. Every town standing more than 6 empty squares from its
-- nearest neighbour moves to the closest free spot by the centre: all its
-- plots shift together (its buildings ride along on them), the founding gap of
-- 2 squares is kept, and no building is put on water. Towns are taken nearest
-- the centre first, so the strays join the realm as it stands.
--
-- Water is a hash of world coordinates in shared/utils/gamelogic/town.ts, so
-- it is written out below: one row per plot within 24 squares of the centre
-- that has any, bit (ty * 8 + tx) set for each water tile. A spot whose land
-- would leave that square is never chosen.
CREATE TEMP TABLE "gather_water" ("px" integer NOT NULL, "py" integer NOT NULL, "mask" bigint NOT NULL, PRIMARY KEY ("px", "py"));--> statement-breakpoint
--> statement-breakpoint
DO $$
DECLARE
    gap constant integer := 2;
    stray constant integer := 6;
    -- Anchors are tried out to this ring, so a town up to 6 squares wide stays inside the water map.
    max_ring constant integer := 18;
    map_ring constant integer := 24;
    town record;
    anchor record;
    nearest integer;
    idx integer;
    r integer;
    side integer;
    leg integer;
    step integer;
    sx integer;
    sy integer;
    dx integer;
    dy integer;
BEGIN
    -- The lock founding and plot buys take, and every town's own lock, so
    -- nothing claims land or settles a town while it moves.
    PERFORM pg_advisory_xact_lock(761442020);
    PERFORM 1 FROM "town_state" FOR UPDATE;

    CREATE TEMP TABLE "gather_placed" ("x" integer NOT NULL, "y" integer NOT NULL);
    CREATE TEMP TABLE "gather_occupied" ("x" integer NOT NULL, "y" integer NOT NULL, PRIMARY KEY ("x", "y"));

    FOR town IN
        SELECT "user_id", min(greatest(abs("x"), abs("y"))) AS "ring", min("created_at") AS "founded"
        FROM "town_plots" GROUP BY "user_id" ORDER BY 2, 3, 1
    LOOP
        SELECT min(greatest(abs(p."x" - q."x"), abs(p."y" - q."y"))) - 1 INTO nearest
        FROM "town_plots" p CROSS JOIN "gather_placed" q
        WHERE p."user_id" = town."user_id";

        IF nearest IS NOT NULL AND nearest > stray THEN
            -- The first-founded plot is the anchor the rest of the town keeps its shape around.
            SELECT "x", "y" INTO anchor FROM "town_plots" WHERE "user_id" = town."user_id" ORDER BY "created_at", "id" LIMIT 1;
            FOR idx IN 0 .. (2 * max_ring + 1) * (2 * max_ring + 1) - 1 LOOP
                -- townSpiralCoords
                IF idx = 0 THEN
                    sx := 0;
                    sy := 0;
                ELSE
                    r := ceil((sqrt(idx + 1) - 1) / 2)::integer;
                    side := r * 2;
                    leg := (idx - (side - 1) * (side - 1)) / side;
                    step := (idx - (side - 1) * (side - 1)) % side;
                    IF leg = 0 THEN sx := r; sy := -r + 1 + step;
                    ELSIF leg = 1 THEN sx := r - 1 - step; sy := r;
                    ELSIF leg = 2 THEN sx := -r; sy := r - 1 - step;
                    ELSE sx := -r + 1 + step; sy := -r;
                    END IF;
                END IF;
                dx := sx - anchor."x";
                dy := sy - anchor."y";

                CONTINUE WHEN EXISTS (
                    SELECT 1 FROM "town_plots" p
                    WHERE p."user_id" = town."user_id"
                      AND (greatest(abs(p."x" + dx), abs(p."y" + dy)) > map_ring
                        OR EXISTS (SELECT 1 FROM "gather_occupied" o WHERE o."x" = p."x" + dx AND o."y" = p."y" + dy)
                        OR EXISTS (SELECT 1 FROM "gather_placed" q WHERE greatest(abs(p."x" + dx - q."x"), abs(p."y" + dy - q."y")) <= gap))
                );
                CONTINUE WHEN EXISTS (
                    SELECT 1
                    FROM "town_buildings" b
                    JOIN "town_plots" p ON p."id" = b."plot_id"
                    JOIN "gather_water" w ON w."px" = p."x" + dx AND w."py" = p."y" + dy
                    CROSS JOIN LATERAL (SELECT CASE b."type" WHEN 'pyramid' THEN 3 WHEN 'colosseum' THEN 3 WHEN 'lighthouse' THEN 2 WHEN 'arc' THEN 2 WHEN 'eiffel' THEN 2 ELSE 1 END AS "size") s
                    CROSS JOIN LATERAL generate_series(0, s."size" - 1) fx
                    CROSS JOIN LATERAL generate_series(0, s."size" - 1) fy
                    WHERE p."user_id" = town."user_id"
                      AND b."tile_x" + fx BETWEEN 0 AND 7
                      AND b."tile_y" + fy BETWEEN 0 AND 7
                      AND (w."mask" >> ((b."tile_y" + fy) * 8 + b."tile_x" + fx)) & 1 = 1
                );

                DELETE FROM "gather_occupied" o USING "town_plots" p
                WHERE p."user_id" = town."user_id" AND o."x" = p."x" AND o."y" = p."y";
                UPDATE "town_plots" SET "x" = "x" + dx, "y" = "y" + dy WHERE "user_id" = town."user_id";
                RAISE NOTICE 'Polytown: moved the town of % from (%, %) to (%, %)', town."user_id", anchor."x", anchor."y", sx, sy;
                EXIT;
            END LOOP;
        END IF;
    END LOOP;

    DROP TABLE "gather_placed";
    DROP TABLE "gather_occupied";
END $$;--> statement-breakpoint
DROP TABLE "gather_water";
